package org.tomdang.entityai.configuration;
import org.bukkit.configuration.ConfigurationSection;import java.util.*;
public final class AiProfileLoader{
	private static final Set<String> TYPES=Set.of("IDLE","REST","WANDER","INVESTIGATE_PLAYER","FLEE_FROM_PLAYER","FOLLOW_OWNER","RETURN_HOME","PATROL","CHASE","ATTACK","SETTLE");private static final Set<String> NAVIGATORS=Set.of("NATIVE_GROUND","DIRECT_FLIGHT");
	public AiProfile load(ConfigurationSection section){if(section==null)throw new IllegalArgumentException("Missing ai section");String navigator=require(section,"navigator").toUpperCase(Locale.ROOT);if(!NAVIGATORS.contains(navigator))throw new IllegalArgumentException("Unknown AI navigator "+navigator);ConfigurationSection goalsSection=section.getConfigurationSection("goals");if(goalsSection==null||goalsSection.getKeys(false).isEmpty())throw new IllegalArgumentException("AI profile requires goals");List<AiGoalDefinition> goals=new ArrayList<>();for(String id:goalsSection.getKeys(false)){ConfigurationSection value=goalsSection.getConfigurationSection(id);if(value==null)throw new IllegalArgumentException("AI goal "+id+" must be a section");String type=require(value,"type").toUpperCase(Locale.ROOT);if(!TYPES.contains(type))throw new IllegalArgumentException("Unknown AI goal type "+type);int priority=value.getInt("priority",-1);Map<String,String> parameters=new LinkedHashMap<>();for(String key:value.getKeys(false))if(!key.equals("type")&&!key.equals("priority")){Object raw=value.get(key);if(raw instanceof ConfigurationSection||raw instanceof List<?>)throw new IllegalArgumentException("AI goal parameter "+key+" must be scalar");parameters.put(key,String.valueOf(raw));}goals.add(new AiGoalDefinition(id,type,priority,parameters));}return new AiProfile(navigator,goals);}
	private String require(ConfigurationSection section,String key){String value=section.getString(key);if(value==null||value.isBlank())throw new IllegalArgumentException("Missing AI "+key);return value;}
}
